9	/**
10	 * TemporalHeartbeatLimb - The Sovereign Heartbeat Motor.
11	 * 
12	 * Orchestrates the dual-rate pulse:
13	 *  - 600ms: Atomic World Tick (Physics, Movement, Cache Logic).
14	 *  - 6000ms: Cognitive Player Tick (Ollama Intents, High-level Strategy).
15	 */
16	export class TemporalHeartbeatLimb {
17	    private static instance: TemporalHeartbeatLimb;
18	    private worldInterval: NodeJS.Timeout | null = null;
19	    private worldTickCount: number = 0;
20	
21	    private readonly WORLD_TICK_MS = 600;
22	    private readonly PLAYER_TICK_RATIO = 1; // 1:1 synchronization for pro-player reaction time
23	    private isCognitiveBusy = false;
24	
25	    private constructor() {
26	        logger.info('TemporalHeartbeatLimb online. 600ms Synchronous Pulse established.');
27	    }
28	
29	    public static getInstance(): TemporalHeartbeatLimb {
30	        if (!TemporalHeartbeatLimb.instance) {
31	            TemporalHeartbeatLimb.instance = new TemporalHeartbeatLimb();
32	        }
33	        return TemporalHeartbeatLimb.instance;
34	    }
35	
36	    /**
37	     * start - Initiates the dual-rate heartbeat.
38	     */
39	    public start(): void {
40	        if (this.worldInterval) return;
41	
42	        logger.info('Sovereign Heartbeat started. Synchronizing world/player loops.');
43	
44	        this.worldInterval = setInterval(async () => {
45	            await this.pulse();
46	        }, this.WORLD_TICK_MS);
47	    }
48	
49	    /**
50	     * stop - Halts the heartbeat.
51	     */
52	    public stop(): void {
53	        if (this.worldInterval) {
54	            clearInterval(this.worldInterval);
55	            this.worldInterval = null;
56	            logger.info('Sovereign Heartbeat halted.');
57	        }
58	    }
59	
60	    /**
61	     * pulse - Executes a single authoritative world pulse.
62	     */
63	    public async pulse(): Promise<void> {
64	        this.worldTickCount++;
65	
66	        // 1. World Tick (600ms) - Standard RS Heartbeat
67	        const volley = CNSGodheadPulseVolley.getInstance();
68	        const switchboard = SwitchboardLimb.getInstance();
69	
70	        try {
71	            const pending = switchboard.drainAdminQueue();
72	            const state = await volley.pulse(pending);
73	
74	            // 2. Spatial Radar Update (Sensory Cortex)
75	            // Render the world state to the CLI for grounding verification
76	            const renderer = volley.getRenderer();
77	            const avatar = volley.getAvatar();
78	            if (renderer && state && avatar) {
79	                const radar = (await import('../spatial/SpatialRadarLimb.js')).SpatialRadarLimb.getInstance();
80	                const grid = radar.render(state, avatar);
81	                renderer.drawRadar(grid);
82	            }
83	
84	            // 3. Pro-Player Cognitive Tick (Sync 1:1)
85	            // Skip-on-Busy Guard: Never block the heartbeat if the brain is still thinking
86	            if (!this.isCognitiveBusy) {
87	                this.emitPlayerPulse();
88	            } else {
89	                logger.warn({ tick: this.worldTickCount }, 'Cognitive Skip: Substrate busy. Droping tick to maintain authority.');
90	            }
91	
92	        } catch (e: any) {
93	            logger.error({ error: e.message, tick: this.worldTickCount }, 'Heartbeat pulse volley failure.');
94	        }
95	    }
96	
97	    private async emitPlayerPulse(): Promise<void> {
98	        this.isCognitiveBusy = true;
99	        try {
100	            const playerTickNum = this.worldTickCount;
101	            logger.info({ tick: playerTickNum }, 'Emitting 600ms Pro-Player Cognitive Pulse.');
102	
103	            const volley = CNSGodheadPulseVolley.getInstance();
104	            const avatar = volley.getAvatar();
105	            if (avatar) {
106	                const playerAgent = new PlayerAgent(avatar as SovereignAvatarEntity);
107	                playerAgent.advanceTick(this.WORLD_TICK_MS);
108	
109	                // Tactical Evaluation (Safespotting Override)
110	                // Retrieve the field just broadcasted by CNSGodheadPulseVolley
111	                const GhostSplatEngine = (await import('../../substrates/GhostSplatEngine.js')).GhostSplatEngine;
112	                const field = GhostSplatEngine.getInstance().getLatestField();
113	                if (field) {
114	                    await playerAgent.evaluateTacticalPosition(field);
115	
116	                    // Combat Evaluation (CombatRotationEngine)
117	                    if (avatar.metadata.tacticalState !== 'evading') {
118	                        const intent = playerAgent.evaluateCombatRotation(field, playerTickNum);
119	                        if (intent) {
120	                            avatar.intent = intent as any;
121	                        }
122	                    }
123	                }
124	            }
125	
126	            // Phase 28: Trigger OllamaCognitiveLimb
127	            // await OllamaCognitiveLimb.getInstance().process(playerTickNum);
128	
129	        } finally {
130	            this.isCognitiveBusy = false;
131	        }
132	    }
133	
134	    public getStatus() {
135	        return {
136	            active: !!this.worldInterval,
137	            worldTick: this.worldTickCount,
138	            playerTick: this.worldTickCount,
139	            frequency: { world: '600ms', cognitive: '600ms (Authoritative)' },
140	            isBusy: this.isCognitiveBusy
141	        };
142	    }
143	}
