16	export class TransientObserver {
17	    private static instance: TransientObserver | undefined;
18	    private eye: any = null;
19	    private lastCaptureTime = 0;
20	    private lastCaptureResult: any = null;
21	    private static readonly CAPTURE_THROTTLE_MS = 5000; // Live vision loop cadence
