53	 */
54	export class SovereignEye extends EventEmitter {
55	    private readonly captureDir: string;
56	
57	    constructor(projectId: string = 'guest') {
58	        super();
59	        this.captureDir = join(getDashboardPath(projectId), 'sovereign_eye');
60	        if (!existsSync(this.captureDir)) {
