67	     * @param options.autoCleanup If true (default), deletes the image file after processing is complete.
68	     */
69	    async capture(source: CaptureSource, viewport: ViewportConfig = DEFAULT_VIEWPORT, options: { autoCleanup?: boolean } = { autoCleanup: true }): Promise<Result<CaptureResult>> {
70	        logger.info({ sourceType: source.type, target: source.target }, 'Sovereign Eye capturing');
71	
72	        let result: Result<CaptureResult>;
73	        switch (source.type) {
74	            case 'url':
75	                result = await this.captureUrl(source.target, viewport);
76	                break;
77	            case 'html':
78	                result = await this.captureHtmlFile(source.target, viewport);
79	                break;
80	            case 'rsc':
81	                result = await this.captureRSC();
82	                break;
83	            case 'window':
84	                result = await this.captureWindow(source.target);
85	                break;
86	            case 'file':
87	                result = await this.captureFile(source.target);
88	                break;
89	            default:
90	                return { ok: false, error: new Error(`Unknown capture source type`) };
91	        }
92	
93	        if (result.ok && options.autoCleanup && result.value.imagePath) {
94	            await this.cleanup(result.value.imagePath);
95	            return { ok: true, value: { ...result.value, imagePath: null } };
