117	     */
118	    private async captureUrl(url: string, viewport: ViewportConfig): Promise<Result<CaptureResult>> {
119	        const timestamp = Date.now();
120	        const screenshotPath = join(this.captureDir, `url_${timestamp}.png`);
121	
122	        try {
123	            // 1. Attempt headless Chrome/Edge screenshot
124	            const screenshotResult = await this.headlessScreenshot(url, screenshotPath, viewport);
125	
126	            // 2. Always fetch text content as fallback/supplement
127	            let textContent: string | null = null;
128	            let attempts = 0;
129	            const maxAttempts = 3;
130	
131	            while (attempts < maxAttempts && !textContent) {
132	                attempts++;
133	                try {
134	                    const controller = new AbortController();
135	                    const timeoutId = setTimeout(() => controller.abort(), 15000); // Extended to 15s
136	                    
137	                    const response = await undiciFetch(url, { 
138	                        signal: controller.signal,
139	                        headers: { 'User-Agent': 'SovereignEye/2.0' }
140	                    });
141	                    clearTimeout(timeoutId);
142	                    
143	                    if (response.ok) {
144	                        textContent = await response.text();
145	                        // Trim for AI context
146	                        if (textContent.length > 10000) {
147	                            textContent = textContent.substring(0, 10000) + '\n... [truncated]';
148	                        }
149	                    } else {
150	                        throw new Error(`HTTP ${response.status}`);
151	                    }
152	                } catch (fetchErr: any) {
153	                    const isTimeout = fetchErr.name === 'AbortError' || fetchErr.message?.includes('Timeout');
154	                    if (attempts < maxAttempts) {
155	                        logger.warn({ url, attempt: attempts, isTimeout }, 'Text fetch failed, retrying...');
156	                        await new Promise(res => setTimeout(res, 2000 * attempts)); // Exponential backoff
157	                    } else {
158	                        if (isTimeout) {
159	                            logger.warn({ url }, 'Text fetch timed out (15s) after 3 attempts, screenshot-only mode');
160	                        } else {
161	                            logger.warn({ err: fetchErr.message, url }, 'Text fetch failed after 3 attempts, screenshot-only mode');
162	                        }
163	                    }
164	                }
165	            }
166	
167	            if (!screenshotResult.ok && !textContent) {
168	                return { ok: false, error: new Error(`Capture failed: No screenshot and no text content could be retrieved.`) };
169	            }
170	
171	            const result: CaptureResult = {
172	                imagePath: screenshotResult.ok ? screenshotPath : null,
173	                textContent,
174	                sourceType: 'url',
175	                metadata: { url, viewport, hasScreenshot: screenshotResult.ok },
176	                timestamp
177	            };
178	
179	            if (screenshotResult.ok) {
180	                await this.cleanupOldCaptures();
181	            }
182	
183	            this.emit('capture', result);
184	
185	            return {
186	                ok: true,
187	                value: result
188	            };
