259	        try {
260	            const psScript = `
261	Add-Type -AssemblyName System.Drawing
262	Add-Type -AssemblyName System.Windows.Forms
263	$procs = Get-Process | Where-Object { $_.MainWindowTitle -like "*${windowTitle.replace(/"/g, '`"')}*" } | Select-Object -First 1
264	if (-not $procs) { exit 1 }
265	Add-Type @"
266	using System;
267	using System.Runtime.InteropServices;
268	public class Win32 {
269	    [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr hWnd, out RECT rect);
270	    [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
271	    [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left, Top, Right, Bottom; }
272	}
273	"@
274	$hwnd = $procs.MainWindowHandle
275	[Win32]::SetForegroundWindow($hwnd) | Out-Null
276	Start-Sleep -Milliseconds 200
277	$rect = New-Object Win32+RECT
278	[Win32]::GetWindowRect($hwnd, [ref]$rect) | Out-Null
279	$width = $rect.Right - $rect.Left
280	$height = $rect.Bottom - $rect.Top
281	$bitmap = New-Object System.Drawing.Bitmap($width, $height)
282	$graphics = [System.Drawing.Graphics]::FromImage($bitmap)
283	$graphics.CopyFromScreen($rect.Left, $rect.Top, 0, 0, [System.Drawing.Size]::new($width, $height))
