334	    private async headlessScreenshot(
335	        url: string,
336	        outputPath: string,
337	        viewport: ViewportConfig
338	    ): Promise<Result<{ path: string }>> {
339	        const browsers = [
340	            'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe',
341	            'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe',
342	            'msedge',
343	            'chrome'
344	        ];
345	
346	        for (const browser of browsers) {
347	            try {
348	                const browserTimeout = 5000; // Reduced to 5s for faster port switching
349	                const cmd = `"${browser}" --headless --disable-gpu --screenshot="${outputPath}" --window-size=${viewport.width},${viewport.height} --hide-scrollbars --no-sandbox "${url}"`;
350	                await execAsync(cmd, { timeout: browserTimeout });
351	
352	                if (existsSync(outputPath)) {
