363	    private async cleanupOldCaptures(maxFiles: number = 50): Promise<void> {
364	        try {
365	            const entries = await fsPromises.readdir(this.captureDir);
366	            const imageFiles = entries.filter(name => /\.(png|jpg|jpeg|webp|gif)$/i.test(name));
367	
368	            if (imageFiles.length <= maxFiles) {
369	                return;
370	            }
371	
372	            const imageStats = await Promise.all(imageFiles.map(async (name) => {
373	                const fullPath = join(this.captureDir, name);
374	                const stat = await fsPromises.stat(fullPath);
375	                return { name, path: fullPath, mtimeMs: stat.mtimeMs };
376	            }));
377	
378	            imageStats.sort((a, b) => a.mtimeMs - b.mtimeMs);
379	            const deleteCount = imageStats.length - maxFiles;
380	
381	            for (let i = 0; i < deleteCount; i += 1) {
382	                const filePath = imageStats[i].path;
383	                if (/pipelines|icons/i.test(filePath)) continue;
384	                await fsPromises.unlink(filePath);
385	            }
386	
387	            logger.info({ deleted: deleteCount, keep: maxFiles }, 'SovereignEye pruned old capture artifacts');
388	        } catch (err) {
389	            logger.warn({ err }, 'Failed to prune old SovereignEye capture artifacts');
390	        }
391	    }
