2	import { Engine, Scene, Mesh, VertexData, StandardMaterial, Color3, ArcRotateCamera, Vector3, HemisphericLight, PointsCloudSystem, Color4 } from '@babylonjs/core';
3	import { AvatarStateLimb } from './AvatarStateLimb.js';
4	
5	const logger = createLogger('AvatarRenderLimb');
6	
7	export class AvatarRenderLimb {
8	    private engine: Engine | null = null;
9	    private scene: Scene | null = null;
10	    private pcs: PointsCloudSystem | null = null;
11	    private state: AvatarStateLimb;
12	    
13	    constructor(private canvas: HTMLCanvasElement) {
14	        this.state = AvatarStateLimb.getInstance();
15	    }
16	    
17	    async initialize(): Promise<void> {
18	        this.engine = new Engine(this.canvas, true);
19	        this.scene = new Scene(this.engine);
20	        this.scene.clearColor = new Color4(0.05, 0.05, 0.05, 1);
21	        
22	        // Camera: orbit around origin
23	        const camera = new ArcRotateCamera('camera', -Math.PI / 2, Math.PI / 2.5, 200, Vector3.Zero(), this.scene);
24	        camera.attachControl(this.canvas, true);
25	        camera.wheelPrecision = 10;
26	        
27	        // Lighting: PBR-ready
28	        new HemisphericLight('light', new Vector3(0, 1, 0), this.scene);
29	        
30	        logger.info('AvatarRenderLimb initialized');
31	    }
32	    
33	    async loadKitModel(modelId: number): Promise<void> {
34	        const meshData = await this.loadMeshJson(modelId);
35	        if (!meshData) {
36	            logger.error({ modelId }, 'Kit model not found');
37	            return;
38	        }
39	        
40	        // Use PointsCloudSystem since we only have raw position geometry from Beta Opcoder
41	        if (this.pcs) {
42	            this.pcs.dispose();
43	        }
44	        
45	        this.pcs = new PointsCloudSystem(`pcs_${modelId}`, 2, this.scene!);
46	        
47	        // Extract PBR skin color from AvatarStateLimb (e.g. Enum 1195 RGB)
48	        const skinRgb = 12104087; // Fallback to our default parsed RGB
49	        const color = this.unpackRgb(skinRgb);
50	        
51	        const positions = meshData.positions;
52	        const pointCount = positions.length / 3;
53	        
54	        this.pcs.addPoints(pointCount, (particle, i) => {
55	            particle.position = new Vector3(
56	                positions[i * 3],
57	                positions[i * 3 + 1],
58	                positions[i * 3 + 2]
59	            );
60	            particle.color = new Color4(color.r, color.g, color.b, 1);
61	        });
62	        
63	        await this.pcs.buildMeshAsync();
64	        
65	        // Auto-center camera on the point cloud bounds
66	        if (this.scene?.activeCamera && this.pcs.mesh) {
67	            (this.scene.activeCamera as ArcRotateCamera).target = this.pcs.mesh.getBoundingInfo().boundingBox.center;
68	        }
69	        
70	        logger.info({ modelId, vertices: pointCount }, 'Kit point-cloud topology rendered');
71	    }
72	    
73	    private unpackRgb(packed: number): Color3 {
74	        const r = ((packed >> 16) & 0xFF) / 255;
75	        const g = ((packed >> 8) & 0xFF) / 255;
76	        const b = (packed & 0xFF) / 255;
77	        return new Color3(r, g, b);
78	    }
79	    
80	    private async loadMeshJson(modelId: number): Promise<any | null> {
81	        try {
82	            // Check if running in browser vs Node
83	            if (typeof window !== 'undefined' && typeof fetch === 'function') {
84	                const res = await fetch(`/models/kit_${modelId}.json`);
85	                return await res.json();
86	            } else {
87	                const fs = await import('fs/promises');
88	                const path = `D:/sovereign/cache_pedagogy/models/kit_${modelId}.json`;
89	                const data = await fs.readFile(path, 'utf8');
90	                return JSON.parse(data);
91	            }
92	        } catch {
93	            return null;
94	        }
95	    }
96	    
97	    renderLoop(): void {
98	        this.engine?.runRenderLoop(() => {
99	            this.scene?.render();
100	        });
101	    }
102	    
103	    dispose(): void {
104	        this.scene?.dispose();
105	        this.engine?.dispose();
106	    }
107	}
